def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    colors = {v for row in grid for v in row}
    background = max(colors, key=lambda v: sum(row.count(v) for row in grid))

    for color in colors - {background}:
        pts = [(r, c) for r in range(h) for c in range(w)
               if grid[r][c] == color]
        if len(pts) < 2:
            continue

        pair = None
        for r, c in pts:
            for dr, dc in ((1, 1), (1, -1)):
                if (r + dr, c + dc) in pts:
                    pair = (r, c, dr, dc)
                    break
            if pair:
                break
        if not pair:
            continue

        r, c, dr, dc = pair
        line = [(r, c), (r + dr, c + dc)]
        others = [(rr, cc) for rr in range(h) for cc in range(w)
                  if grid[rr][cc] not in (background, color)]
        if others:
            cr = sum(rr for rr, _ in others) / len(others)
            cc = sum(cc for _, cc in others) / len(others)
            # Extend from the end farther from the other colored objects.
            d0 = (line[0][0] - cr) ** 2 + (line[0][1] - cc) ** 2
            d1 = (line[1][0] - cr) ** 2 + (line[1][1] - cc) ** 2
            if d0 > d1:
                r, c, dr, dc = line[0][0], line[0][1], -dr, -dc
            else:
                r, c = line[1]
        else:
            r, c = line[1]

        r += dr
        c += dc
        while 0 <= r < h and 0 <= c < w:
            if grid[r][c] == background:
                out[r][c] = color
            r += dr
            c += dc
    return out
